UPDATE users
SET fail_count = fail_count + 1,
    updated_at = #{now}
WHERE username = #{username}
  AND deleted_at IS NULL

UPDATE users
SET fail_count   = 0,
    last_login_at = #{now},
    updated_at   = #{now}
WHERE username = #{username}
  AND deleted_at IS NULL

UPDATE users
SET last_login_at = #{now},
    updated_at    = #{now}
WHERE id = #{id}

UPDATE users
SET status     = 'DELETED',
    deleted_at = #{deletedAt},
    updated_at = #{deletedAt}
WHERE id = #{id}
  AND deleted_at IS NULL

