UPDATE users
SET status       = 'ACTIVE',
    locked_until = NULL,
    fail_count   = 0,
    updated_at   = #{now}
WHERE id = #{id}

UPDATE users
SET password_hash       = #{hash},
    password_changed_at = #{now},
    updated_at          = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL

UPDATE users
SET organization_id = #{organizationId},
    updated_at      = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL
